export type ColumnId = 'todo' | 'doing' | 'done';
export interface CardItem { id: string; title: string; column: ColumnId }
export type BoardAction =
  | { type: 'add'; title: string; column: ColumnId }
  | { type: 'move'; id: string; column: ColumnId }
  | { type: 'delete'; id: string };

export function boardReducer(cards: CardItem[], action: BoardAction): CardItem[] {
  switch (action.type) {
    case 'add': return [...cards, { id: crypto.randomUUID(), title: action.title, column: action.column }];
    case 'move': return cards.map((c) => (c.id === action.id ? { ...c, column: action.column } : c));
    case 'delete': return cards.filter((c) => c.id !== action.id);
  }
}

import { useDeferredValue, useMemo, useReducer, useState } from 'react';
import { boardReducer, type ColumnId } from './boardReducer';
const COLS: ColumnId[] = ['todo', 'doing', 'done'];
export function BoardView() {
  const [cards, dispatch] = useReducer(boardReducer, []);
  const [q, setQ] = useState('');
  const dq = useDeferredValue(q);
  const filtered = useMemo(() => cards.filter((c) => c.title.toLowerCase().includes(dq.toLowerCase())), [cards, dq]);
  return (
    <section>
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Filter tasks..." />
      <div className="grid gap-4 md:grid-cols-3">
        {COLS.map((col) => (
          <div key={col}>
            <h3>{col}</h3>
            {filtered.filter((c) => c.column === col).map((c) => <article key={c.id}>{c.title}</article>)}
          </div>
        ))}
      </div>
    </section>
  );
}
